export function buildTypeParameters(
	value: AdmitBound<T.TypeParametersElements, T.AdmittedNodes>
): ReturnType<typeof _buildTypeParameters>;
export function buildTypeParameters(
	options: { delimiter?: Delimiter.None | Delimiter.Trailing },
	...elements: NonEmptyArray<
		AdmitBound<
			T.AttributedTypeParameter | T.Metavariable | T.TypeParameter | T.LifetimeParameter | T.ConstParameter,
			T.AdmittedNodes
		>
	>
): ReturnType<typeof _buildTypeParameters>;
export function buildTypeParameters(
	...elements: NonEmptyArray<
		AdmitBound<
			T.AttributedTypeParameter | T.Metavariable | T.TypeParameter | T.LifetimeParameter | T.ConstParameter,
			T.AdmittedNodes
		>
	>
): ReturnType<typeof _buildTypeParameters>;
export function buildTypeParameters(...args: unknown[]) {
	if (args.length === 0 || (args.length === 1 && args[0] === undefined)) {
		return _buildTypeParameters(args[0] as T.TypeParametersElements);
	}
	const prebuilt =
		args.length === 1 &&
		typeof args[0] === 'object' &&
		args[0] !== null &&
		(args[0] as { $type?: unknown }).$type === (TSKindId.TypeParametersElements as const);
	return prebuilt
		? _buildTypeParameters(args[0] as T.TypeParametersElements)
		: _buildTypeParameters(
				(buildTypeParametersElements as (...a: unknown[]) => unknown)(...args) as T.TypeParametersElements
			);
}
function _buildTypeParameters(value: AdmitBound<T.TypeParametersElements, T.AdmittedNodes>): T.TypeParameters.Bound {
	const _type_parameters_elements = rejectBareText(
		value,
		'TypeParameters.typeParametersElements',
		'a built TypeParametersElements'
	);
	return withMethods(
		withListView(
			withListSlots(
				withAccessors(
					{
						$type: TSKindId.TypeParameters as const,
						$source: 2 as const,
						$named: true as const,
						_type_parameters_elements,
						$with: {
							typeParametersElements: (value: T.TypeParametersElements) => _buildTypeParameters(value)
						}
					},
					{
						typeParametersElements: () => _type_parameters_elements
					}
				),
				[
					{
						slot: 'typeParametersElements',
						kind: TSKindId.TypeParametersElements as const,
						optional: false,
						make: buildTypeParametersElements,
						element: { keys: ['attributeItem', 'content'], make: buildAttributedTypeParameter }
					}
				]
			),
			{
				list: { accessor: 'typeParametersElements', storage: '_type_parameters_elements' },
				elements: 'elements',
				count: '_element',
				options: [{ key: 'delimiter', default: Delimiter.None }],
				wrapper: { kind: TSKindId.AttributedTypeParameter, content: 'content', decorations: ['_attribute_item'] }
			}
		)
	) as unknown as T.TypeParameters.Bound;
}

